#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef long long int64;

typedef struct {
    int64 value;
    int index;
} Item;

static int n;
static int64 *u, *v;
static Item *orderU, *orderV;
static unsigned char *active;
static signed char *color;
static int *queue;

static int compareItem(const void *a, const void *b) {
    const Item *x = (const Item *)a;
    const Item *y = (const Item *)b;

    if (x->value < y->value) return -1;
    if (x->value > y->value) return 1;
    return (x->index > y->index) - (x->index < y->index);
}

static int feasible(int64 limit) {
    memset(active, 1, (size_t)n);
    memset(color, -1, (size_t)n);

    int64 minU[2], maxU[2], minV[2], maxV[2];
    unsigned char seen[2] = {0, 0};

    int activeCount = n;
    int loU = 0, hiU = n - 1;
    int loV = 0, hiV = n - 1;
    int head = 0, tail = 0, seed = 0;

    while (activeCount > 0) {
        while (seed < n && !active[seed]) seed++;
        if (seed == n) break;

        color[seed] = 0;
        active[seed] = 0;
        activeCount--;
        queue[tail++] = seed;

        while (head < tail) {
            int p = queue[head++];
            int c = color[p];

            if (seen[c]) {
                if (u[p] < minU[c] - limit || u[p] > maxU[c] + limit ||
                    v[p] < minV[c] - limit || v[p] > maxV[c] + limit) {
                    return 0;
                }

                if (u[p] < minU[c]) minU[c] = u[p];
                if (u[p] > maxU[c]) maxU[c] = u[p];
                if (v[p] < minV[c]) minV[c] = v[p];
                if (v[p] > maxV[c]) maxV[c] = v[p];
            } else {
                seen[c] = 1;
                minU[c] = maxU[c] = u[p];
                minV[c] = maxV[c] = v[p];
            }

            while (activeCount > 0) {
                while (loU < n && !active[orderU[loU].index]) loU++;
                while (hiU >= 0 && !active[orderU[hiU].index]) hiU--;
                while (loV < n && !active[orderV[loV].index]) loV++;
                while (hiV >= 0 && !active[orderV[hiV].index]) hiV--;

                int q = -1;
                if (u[orderU[loU].index] < u[p] - limit) {
                    q = orderU[loU].index;
                } else if (u[orderU[hiU].index] > u[p] + limit) {
                    q = orderU[hiU].index;
                } else if (v[orderV[loV].index] < v[p] - limit) {
                    q = orderV[loV].index;
                } else if (v[orderV[hiV].index] > v[p] + limit) {
                    q = orderV[hiV].index;
                }

                if (q == -1) break;

                active[q] = 0;
                activeCount--;
                color[q] = (signed char)(1 - c);
                queue[tail++] = q;
            }
        }
    }

    return 1;
}

static int readInt(void) {
    int c;
    do {
        c = getchar_unlocked();
    } while (c <= ' ' && c != EOF);

    int value = 0;
    while (c > ' ') {
        value = value * 10 + (c - '0');
        c = getchar_unlocked();
    }
    return value;
}

int main(void) {
    n = readInt();

    int64 *x = (int64 *)malloc((size_t)n * sizeof(int64));
    u = (int64 *)malloc((size_t)n * sizeof(int64));
    v = (int64 *)malloc((size_t)n * sizeof(int64));
    orderU = (Item *)malloc((size_t)n * sizeof(Item));
    orderV = (Item *)malloc((size_t)n * sizeof(Item));
    active = (unsigned char *)malloc((size_t)n);
    color = (signed char *)malloc((size_t)n);
    queue = (int *)malloc((size_t)n * sizeof(int));

    for (int i = 0; i < n; i++) x[i] = readInt();

    for (int i = 0; i < n; i++) {
        int64 y = readInt();
        u[i] = x[i] + y;
        v[i] = x[i] - y;
        orderU[i].value = u[i];
        orderU[i].index = i;
        orderV[i].value = v[i];
        orderV[i].index = i;
    }

    free(x);

    qsort(orderU, (size_t)n, sizeof(Item), compareItem);
    qsort(orderV, (size_t)n, sizeof(Item), compareItem);

    int64 low = -1;
    int64 high = 1000000000LL;

    while (high - low > 1) {
        int64 mid = low + (high - low) / 2;
        if (feasible(mid)) high = mid;
        else low = mid;
    }

    printf("%lld\n", high);

    free(u);
    free(v);
    free(orderU);
    free(orderV);
    free(active);
    free(color);
    free(queue);
    return 0;
}
